package com.apiforge.system.service;

import java.time.Clock;
import java.time.Instant;

import org.springframework.beans.factory.ObjectProvider;
import org.springframework.boot.info.BuildProperties;
import org.springframework.stereotype.Service;

/**
 * Describes the running backend. The version comes from the build metadata generated by the
 * Spring Boot Maven plugin; it is reported as "unknown" rather than guessed when the
 * metadata is absent (for example when running from an IDE without a Maven build).
 */
@Service
public class SystemInfoService {

    static final String API_VERSION = "v1";
    static final String UNKNOWN = "unknown";

    private final ObjectProvider<BuildProperties> buildProperties;
    private final Clock clock;

    public SystemInfoService(ObjectProvider<BuildProperties> buildProperties, Clock clock) {
        this.buildProperties = buildProperties;
        this.clock = clock;
    }

    public SystemInfo describe() {
        BuildProperties build = buildProperties.getIfAvailable();
        String version = build != null && build.getVersion() != null ? build.getVersion() : UNKNOWN;
        return new SystemInfo("APIForge AI", version, API_VERSION, Instant.now(clock));
    }

    public record SystemInfo(String name, String version, String apiVersion, Instant serverTime) {
    }
}
